CREATE TABLE IF NOT EXISTS p7_awake_runs (id VARBINARY(64) PRIMARY KEY, player_id BIGINT NOT NULL, copy_id VARCHAR(64) NOT NULL, diagnostic BOOLEAN NOT NULL, start_at BIGINT NOT NULL, end_at BIGINT NOT NULL, freeze LONGBLOB NOT NULL, freeze_hash CHAR(64) NOT NULL, actor LONGBLOB NOT NULL, enter_frame LONGBLOB NOT NULL, INDEX(player_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
